#include "ksPanelMasksTask.h"
#include <stdexcept>
#include <iostream>
#include <vector>
int main(){using T=ks::PanelMasksTask;using K=T::Kind;using S=T::Stage;using R=T::Read;using W=T::Write;unsigned cases=0;auto population=[](unsigned value){unsigned n=0;for(unsigned i=0;i<4;++i)n+=(value>>i)&1;return n;};for(unsigned kind=1;kind<3;++kind)for(unsigned activation=0;activation<256;++activation)for(unsigned pattern=0;pattern<16;++pattern)for(unsigned previous:{0u,255u,85u,170u})for(unsigned toggle:{0u,255u,85u,170u}){T t(kind==1?K::Mask:K::Invert);unsigned used=0,activationReads=0;uint8_t port=0,mask=0;std::vector<unsigned>decays;for(unsigned i=0;i<4;++i)decays.push_back((pattern>>i)&1?37+i*17:0);std::vector<std::pair<W,unsigned>>expected,writes;for(unsigned i=0;i<4;++i){if((activation>>i)&1){decays[i]=kind==1?(decays[i]?0:8):decays[i]|8;expected.emplace_back(W::Decay,decays[i]);}if(kind==1){if(!decays[i])mask|=1u<<(4+i);}else if(decays[i])mask|=1u<<i;}if(kind==1)mask|=15;uint8_t other=0xa5,output=kind==1?uint8_t((toggle&mask)^other):uint8_t((toggle^mask)&other);if(previous!=mask){expected.emplace_back(W::Mask,mask);expected.emplace_back(W::Data,output);expected.emplace_back(W::Port,0x34);expected.emplace_back(W::Strobe,0x14);expected.emplace_back(W::Strobe,0x34);}std::vector<unsigned>memory;for(unsigned i=0;i<4;++i)memory.push_back((pattern>>i)&1?37+i*17:0);while(t.stage()!=S::Complete){auto cost=t.nextClocks();if(t.advanceBefore(cost-1,[](R)->unsigned{throw std::runtime_error("early read");},[](W,uint8_t){throw std::runtime_error("early write");}))throw std::runtime_error("budget");used+=t.advanceBefore(cost,[&](R r)->unsigned{switch(r){case R::ActivationInput:++activationReads;return activation;case R::Decay:return memory[t.index()];case R::Previous:return previous;case R::Toggle:return toggle;case R::Other:return other;case R::Port:return port;default:throw std::runtime_error("unexpected pending read");}},[&](W w,uint8_t value){writes.emplace_back(w,value);if(w==W::Decay)memory[t.index()]=value;if(w==W::Port||w==W::Strobe)port=value;});}unsigned nonzero=0;for(auto value:decays)nonzero+=bool(value);unsigned clocks=(kind==1?157:142)+3*nonzero+(kind==1?21:12)*population(activation)+(previous!=mask?118:0);if(writes!=expected||memory!=decays||used!=clocks||activationReads!=1||t.mask()!=mask||t.index()!=4||t.remaining())throw std::runtime_error("explicit mask/invert input/activation/decay/order/clocks");++cases;}std::cout<<"PASS: "<<cases<<" pure explicit panel-mask/invert properties\n";}
